import 'package:cloud_firestore/cloud_firestore.dart';

class AurenFoodItem { final String id,ownerId,name,category,city,country,currency,status; final int priceMinor; final bool halal,organic,vegan,vegetarian,athleteFriendly; const AurenFoodItem({required this.id,required this.ownerId,required this.name,required this.category,required this.city,required this.country,required this.currency,required this.priceMinor,required this.halal,required this.organic,required this.vegan,required this.vegetarian,required this.athleteFriendly,required this.status}); factory AurenFoodItem.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final x=d.data()??{};return AurenFoodItem(id:d.id,ownerId:x['ownerId']??'',name:x['name']??'',category:x['category']??'food',city:x['city']??'',country:x['country']??'',currency:x['currency']??'USD',priceMinor:x['priceMinor']??0,halal:x['halal']==true,organic:x['organic']==true,vegan:x['vegan']==true,vegetarian:x['vegetarian']==true,athleteFriendly:x['athleteFriendly']==true,status:x['status']??'active');}}
class AurenFoodService { AurenFoodService._(); static final instance=AurenFoodService._(); final _db=FirebaseFirestore.instance;
Stream<List<AurenFoodItem>> watch({String city='',String country='',String category=''})=>_db.collection('food_items').where('status',isEqualTo:'active').limit(100).snapshots().map((s){final c=city.trim().toLowerCase(),co=country.trim().toLowerCase(),ca=category.trim().toLowerCase();return s.docs.map(AurenFoodItem.fromDoc).where((x)=>(c.isEmpty||x.city.toLowerCase()==c)&&(co.isEmpty||x.country.toLowerCase()==co)&&(ca.isEmpty||x.category.toLowerCase()==ca)).toList();});
Future<String> create({required String ownerId,required String name,required String category,required String city,required String country,required String currency,required int priceMinor,required bool halal,required bool organic,required bool vegan,required bool vegetarian,required bool athleteFriendly})async{if(ownerId.isEmpty||name.trim().isEmpty||city.trim().isEmpty||country.trim().isEmpty)throw ArgumentError('بيانات الطعام الأساسية مطلوبة.');if(priceMinor<0)throw ArgumentError('السعر غير صالح.');final r=_db.collection('food_items').doc();await r.set({'ownerId':ownerId,'name':name.trim(),'category':category.trim(),'city':city.trim(),'country':country.trim(),'currency':currency.trim().toUpperCase(),'priceMinor':priceMinor,'halal':halal,'organic':organic,'vegan':vegan,'vegetarian':vegetarian,'athleteFriendly':athleteFriendly,'status':'active','createdAt':FieldValue.serverTimestamp()});return r.id;}
}